/**
 * Static site generator for tiersaver.com.
 *
 *   node build/build.mjs           write the generated files into site/
 *   node build/build.mjs --check   write nothing; exit 1 if a generated file
 *                                  differs from what is on disk
 *
 * Input:  src/pages/**\/*.html  page bodies with a front-matter comment
 *         src/partials/*.html   fragments included with {{> name}}
 *         src/data.ts           siteData(): values for {{token}} placeholders
 *         src/check/main.ts     browser script for the list health check
 * Output: one .html per page (same relative path, in the site root),
 *         sitemap.xml, robots.txt and assets/list-check.js.
 *
 * The site root is also the web root (see wrangler.jsonc), so the generated
 * files are committed. test/site.test.ts fails when they are out of date.
 *
 * Page format: the file starts with an HTML comment of "key: value" lines.
 *   title        page title and h1 (required)
 *   seoTitle     shorter text for <title> and og:title, when the h1 is too long for them
 *   description  meta description (required)
 *   layout       "landing" (body is the whole <main>) or "doc" (article with
 *                breadcrumb, header and a sidebar listing its group)
 *   group        "help", "guide" or "legal"; decides breadcrumb and sidebar
 *   nav          short name used in navigation lists (doc pages)
 *   summary      one line shown on the help center cards
 *   lead         intro paragraph under the h1 (doc pages)
 *   kicker       label above the h1 (defaults to the group's name)
 *   order        position inside the group
 *   updated      text shown after "Last updated"
 *   script       name of a bundle in assets/ to load with defer
 *   sitemap      "no" leaves the page out of the sitemap and gives it no canonical URL
 *   index        "yes" marks a group's index page (not listed in the group itself)
 *   footer       "yes" lists a help article in the site footer
 *
 * Front-matter values may use {{token}} placeholders too, so a description
 * never types a number that src/data.ts already holds.
 */
import { mkdir, readFile, readdir, writeFile } from "node:fs/promises";
import { dirname, join, relative, sep } from "node:path";
import { pathToFileURL } from "node:url";
import { build as esbuild } from "esbuild";
import { SITE_DIR } from "./assets.mjs";

export { SITE_DIR, ORIGIN, AUDIT_CTA_URL, AUDIT_CTA_LABEL, LEGAL_DRAFT };

const SRC_DIR = join(SITE_DIR, "src");
const PAGES_DIR = join(SRC_DIR, "pages");
const PARTIALS_DIR = join(SRC_DIR, "partials");

/**
 * The public address of the site, written here and nowhere else in site/: canonical URLs, Open Graph, structured
 * data, sitemap.xml, robots.txt and the link checker (check-links.mjs imports it) all read this constant.
 * The values that change on launch day are listed by `node scripts/dia-d.mjs` at the repo root.
 */
const ORIGIN = "https://tiersaver.com";
const SITE_NAME = "TierSaver";
const TAGLINE = "Automatic list hygiene for Klaviyo";
const LEGAL_ENTITY = "Digital Solvers LLC";
const COPYRIGHT_YEAR = "2026";
const THEME_COLOR = "#eeeeec";
const CONTACT_EMAIL = "hello@tiersaver.com";
const SUPPORT_EMAIL = "support@tiersaver.com";

/**
 * Where every "Run my free list audit" button goes.
 * TODO: this must point to the Shopify App Store listing once it exists
 * (https://apps.shopify.com/<handle>). Until then it opens an email, and
 * AUDIT_CTA_NOTE says so next to the main button. When the listing is live,
 * change the URL here and set AUDIT_CTA_NOTE to "".
 */
const AUDIT_CTA_URL = `mailto:${CONTACT_EMAIL}?subject=Free%20list%20audit`;
const AUDIT_CTA_LABEL = "Run my free list audit";
const AUDIT_CTA_NOTE = ` TierSaver is not on the Shopify App Store yet, so the button opens an email to ${CONTACT_EMAIL}.`;

/**
 * The one switch for the legal pages (group "legal": terms, privacy, DPA).
 * While true they carry the draft banner, are left out of the sitemap, have no
 * canonical URL and ask search engines not to index them. Set it to false only
 * when the lawyer has approved the final text.
 */
const LEGAL_DRAFT = true;

const GROUPS = {
  help: { label: "Help center", crumb: { href: "/help/", text: "Help center" } },
  guide: { label: "Guides", crumb: { href: "/help/", text: "Help center" } },
  legal: { label: "Legal", crumb: null },
};

const SCRIPT_BANNER =
  "/* TierSaver list health check. Generated by build/build.mjs from src/check and @tiersaver/core. Do not edit. */";

/** Escapes text for HTML content and double-quoted attribute values. */
function esc(text) {
  return String(text).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

async function walk(dir) {
  const out = [];
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) out.push(...(await walk(full)));
    else out.push(full);
  }
  return out.sort();
}

/** Splits a page source into its front-matter fields and its body. */
function parsePage(file, source) {
  const text = source.replace(/\r\n/g, "\n");
  const match = /^<!--\n([\s\S]*?)\n-->\n?/.exec(text);
  if (!match) throw new Error(`${file}: missing front-matter comment`);
  const meta = {};
  for (const line of match[1].split("\n")) {
    if (!line.trim()) continue;
    const colon = line.indexOf(":");
    if (colon < 1) throw new Error(`${file}: bad front-matter line "${line}"`);
    meta[line.slice(0, colon).trim()] = line.slice(colon + 1).trim();
  }
  for (const key of ["title", "description", "layout"]) {
    if (!meta[key]) throw new Error(`${file}: front matter needs "${key}"`);
  }
  if (meta.layout !== "landing" && meta.layout !== "doc") throw new Error(`${file}: unknown layout "${meta.layout}"`);
  if (meta.group && !GROUPS[meta.group]) throw new Error(`${file}: unknown group "${meta.group}"`);
  if (meta.layout === "doc") {
    for (const key of ["group", "nav", "lead", "updated", "order"]) {
      if (!meta[key]) throw new Error(`${file}: doc pages need "${key}"`);
    }
  }
  return { meta, body: text.slice(match[0].length) };
}

/** Site path of a page: "index.html" is "/", "help/index.html" is "/help/", "help/undo.html" is "/help/undo". */
function urlFor(path) {
  const posix = path.split(sep).join("/");
  if (posix === "index.html") return "/";
  if (posix.endsWith("/index.html")) return `/${posix.slice(0, -"index.html".length)}`;
  return `/${posix.slice(0, -".html".length)}`;
}

async function loadPages() {
  const files = (await walk(PAGES_DIR)).filter((f) => f.endsWith(".html"));
  return Promise.all(
    files.map(async (file) => {
      const path = relative(PAGES_DIR, file);
      const { meta, body } = parsePage(relative(SITE_DIR, file), await readFile(file, "utf8"));
      return { path, url: urlFor(path), meta, body, order: Number(meta.order ?? 0) };
    }),
  );
}

async function loadPartials() {
  const partials = new Map();
  for (const file of await walk(PARTIALS_DIR)) {
    if (!file.endsWith(".html")) continue;
    const name = relative(PARTIALS_DIR, file).split(sep).join("/").slice(0, -".html".length);
    partials.set(name, (await readFile(file, "utf8")).replace(/\r\n/g, "\n"));
  }
  return partials;
}

/** Bundles src/data.ts (TypeScript, imports @tiersaver/core) and returns siteData(). */
async function loadSiteData() {
  const result = await esbuild({
    entryPoints: [join(SRC_DIR, "data.ts")],
    bundle: true,
    write: false,
    format: "iife",
    globalName: "__tiersaverSiteData",
    platform: "neutral",
    mainFields: ["module", "main"],
    target: "es2022",
    logLevel: "silent",
  });
  const code = result.outputFiles[0].text;
  const data = new Function(`${code}\nreturn __tiersaverSiteData.siteData();`)();
  for (const [key, value] of Object.entries(data)) {
    if (typeof value !== "string") throw new Error(`siteData(): "${key}" is not a string`);
  }
  return data;
}

/** Bundles the list health check into one minified script for the browser. */
async function bundleListCheck() {
  const result = await esbuild({
    entryPoints: [join(SRC_DIR, "check", "main.ts")],
    bundle: true,
    write: false,
    format: "iife",
    platform: "browser",
    target: "es2020",
    minify: true,
    legalComments: "none",
    charset: "utf8",
    // Core freezes its constant tables; marking the call as pure lets esbuild
    // drop the ones the browser script never reads.
    pure: ["Object.freeze"],
    banner: { js: SCRIPT_BANNER },
    logLevel: "silent",
  });
  return result.outputFiles[0].text;
}

/** Members of a group in sidebar order, without the group's index page. */
function groupPages(pages, group) {
  return pages.filter((p) => p.meta.group === group && p.meta.index !== "yes").sort((a, b) => a.order - b.order);
}

/** Card grid linking to every page of a group (help center index). */
function linkGrid(pages, group) {
  const items = groupPages(pages, group).map(
    (p) => `        <li>
          <a class="link-card" href="${p.url}">
            <span class="link-card__title">${esc(p.meta.nav)}</span>
            <span class="link-card__text">${esc(p.meta.summary ?? "")}</span>
          </a>
        </li>`,
  );
  return `<ul class="link-grid">\n${items.join("\n")}\n      </ul>`;
}

/** Replaces {{> partial}} includes, then {{token}} placeholders. Unknown names are errors. */
function fill(page, text, tokens, partials) {
  const included = text.replace(/\{\{>\s*([\w./-]+)\s*\}\}\n?/g, (_, name) => {
    const partial = partials.get(name);
    if (partial === undefined) throw new Error(`${page}: unknown partial "${name}"`);
    return partial.endsWith("\n") ? partial : `${partial}\n`;
  });
  return included.replace(/\{\{\s*([\w.-]+)\s*\}\}/g, (_, name) => {
    const value = tokens[name];
    if (value === undefined) throw new Error(`${page}: unknown placeholder "{{${name}}}"`);
    return value;
  });
}

function head(page, tokens) {
  const { meta } = page;
  const listed = isListed(page);
  const shortTitle = meta.seoTitle ?? meta.title;
  const title = shortTitle.includes(SITE_NAME) ? shortTitle : `${shortTitle} · ${SITE_NAME}`;
  const lines = [
    `<meta charset="utf-8">`,
    `<meta name="viewport" content="width=device-width, initial-scale=1">`,
    `<title>${esc(title)}</title>`,
    `<meta name="description" content="${esc(meta.description)}">`,
    listed ? `<link rel="canonical" href="${ORIGIN}${page.url}">` : null,
    isLegalDraft(page) ? `<meta name="robots" content="noindex">` : null,
    `<meta name="theme-color" content="${THEME_COLOR}">`,
    `<meta property="og:site_name" content="${SITE_NAME}">`,
    `<meta property="og:type" content="${meta.layout === "doc" ? "article" : "website"}">`,
    `<meta property="og:locale" content="en_US">`,
    `<meta property="og:title" content="${esc(shortTitle)}">`,
    `<meta property="og:description" content="${esc(meta.description)}">`,
    listed ? `<meta property="og:url" content="${ORIGIN}${page.url}">` : null,
    `<meta property="og:image" content="${ORIGIN}/assets/og-image.png">`,
    `<meta property="og:image:width" content="1200">`,
    `<meta property="og:image:height" content="630">`,
    `<meta property="og:image:alt" content="${SITE_NAME}. ${TAGLINE}.">`,
    `<meta name="twitter:card" content="summary_large_image">`,
    `<link rel="icon" href="/assets/favicon.svg" type="image/svg+xml">`,
    `<link rel="icon" href="/assets/favicon-32.png" type="image/png" sizes="32x32">`,
    `<link rel="apple-touch-icon" href="/assets/apple-touch-icon.png">`,
    `<link rel="preload" href="/fonts/inter-tight-latin-300-normal.woff2" as="font" type="font/woff2" crossorigin>`,
    `<link rel="preload" href="/fonts/inter-tight-latin-400-normal.woff2" as="font" type="font/woff2" crossorigin>`,
    `<link rel="stylesheet" href="/styles/tokens.css">`,
    `<link rel="stylesheet" href="/styles/base.css">`,
    `<link rel="stylesheet" href="/styles/site.css">`,
    meta.script ? `<script src="/assets/${meta.script}.js" defer></script>` : null,
    ...structuredData(page, tokens),
  ];
  return lines
    .filter((line) => line !== null)
    .map((line) => `  ${line}`)
    .join("\n");
}

function siteHeader(page) {
  const helpCurrent = page.meta.group === "help" ? ' aria-current="page"' : "";
  return `  <a class="skip-link" href="#main">Skip to content</a>
  <header class="site-header">
    <div class="container site-header__inner">
      <a class="site-header__logo" href="/" aria-label="${SITE_NAME} home">
        <img src="/assets/logo.svg" alt="${SITE_NAME}" width="133" height="32">
      </a>
      <nav class="site-nav" aria-label="Main">
        <ul>
          <li><a href="/#how-it-works">How it works</a></li>
          <li><a href="/#list-check">List check</a></li>
          <li><a href="/#pricing">Pricing</a></li>
          <li><a href="/#faq">FAQ</a></li>
          <li><a href="/help/"${helpCurrent}>Help</a></li>
        </ul>
      </nav>
      <a class="button button--small site-header__cta" href="${AUDIT_CTA_URL}">${AUDIT_CTA_LABEL}</a>
    </div>
  </header>`;
}

function siteFooter(pages, tokens) {
  const item = (href, text) => `            <li><a href="${href}">${esc(text)}</a></li>`;
  const help = groupPages(pages, "help")
    .filter((p) => p.meta.footer === "yes")
    .map((p) => item(p.url, p.meta.nav));
  const guides = groupPages(pages, "guide").map((p) => item(p.url, p.meta.nav));
  const legal = groupPages(pages, "legal").map((p) => item(p.url, LEGAL_DRAFT ? `${p.meta.nav} (draft)` : p.meta.nav));
  return `  <footer class="site-footer">
    <div class="container">
      <div class="site-footer__top">
        <div class="site-footer__brand">
          <img src="/assets/logo.svg" alt="${SITE_NAME}" width="133" height="32">
          <p class="text-muted small">${TAGLINE}, for Shopify brands.</p>
          <p class="text-muted small">Support: <a href="mailto:${SUPPORT_EMAIL}">${SUPPORT_EMAIL}</a><br>Everything else: <a href="mailto:${CONTACT_EMAIL}">${CONTACT_EMAIL}</a></p>
        </div>
        <nav class="site-footer__col" aria-label="Product">
          <p class="label">Product</p>
          <ul>
            <li><a href="/#how-it-works">How it works</a></li>
            <li><a href="/#list-check">List health check</a></li>
            <li><a href="/#pricing">Pricing</a></li>
            <li><a href="/#faq">Questions</a></li>
          </ul>
        </nav>
        <nav class="site-footer__col" aria-label="Help center">
          <p class="label">Help center</p>
          <ul>
            <li><a href="/help/">All help articles</a></li>
${help.join("\n")}
          </ul>
        </nav>
        <nav class="site-footer__col" aria-label="Guides">
          <p class="label">Guides</p>
          <ul>
${guides.join("\n")}
          </ul>
        </nav>
        <nav class="site-footer__col" aria-label="Legal">
          <p class="label">Legal</p>
          <ul>
${legal.join("\n")}
            <li><a href="/help/data-and-privacy">Data and privacy</a></li>
          </ul>
        </nav>
      </div>
      <div class="site-footer__bottom">
        <p class="small text-muted">${SITE_NAME} is an independent product. It is not affiliated with, endorsed by or sponsored by Klaviyo, Inc. or Shopify Inc. Klaviyo and Shopify are trademarks of their respective owners and are used here only to describe what ${SITE_NAME} works with.</p>
        <p class="small text-muted">Klaviyo plan sizes mentioned on this site were read on ${longDate(tokens["prices.capturedOn"])} and may have changed. ${SITE_NAME} makes no promise about your Klaviyo plan or invoice.</p>
        <p class="small text-muted">© ${COPYRIGHT_YEAR} ${LEGAL_ENTITY}. All rights reserved.</p>
      </div>
    </div>
  </footer>`;
}

const DRAFT_BANNER = `    <div class="draft-banner" role="note">
      <p><strong>Draft under legal review.</strong> The final version will replace this page before ${SITE_NAME} is publicly available.</p>
    </div>
`;

/** True for a legal page while the legal texts are drafts. */
function isLegalDraft(page) {
  return LEGAL_DRAFT && page.meta.group === "legal";
}

/** False for pages that stay out of the sitemap and get no canonical URL. */
function isListed(page) {
  return page.meta.sitemap !== "no" && !isLegalDraft(page);
}

const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

/** "2026-11-25" becomes "November 25, 2026"; any other text is returned as it is. */
function longDate(text) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text);
  return m ? `${MONTHS[Number(m[2]) - 1]} ${Number(m[3])}, ${m[1]}` : text;
}

/** A JSON-LD data block. It is data, not a script the browser runs, so the Content-Security-Policy does not apply to it. */
function jsonLd(data) {
  return `<script type="application/ld+json">${JSON.stringify(data).replace(/</g, "\\u003c")}</script>`;
}

/** Structured data: the organization and the app on the landing page, the breadcrumb trail on articles. Nothing is invented: no ratings, no reviews. */
function structuredData(page, tokens) {
  const { meta } = page;
  if (page.url === "/") {
    const organization = {
      "@type": "Organization",
      "@id": `${ORIGIN}/#organization`,
      name: SITE_NAME,
      legalName: LEGAL_ENTITY,
      url: `${ORIGIN}/`,
      logo: `${ORIGIN}/assets/apple-touch-icon.png`,
      email: CONTACT_EMAIL,
      contactPoint: { "@type": "ContactPoint", contactType: "customer support", email: SUPPORT_EMAIL, url: `${ORIGIN}/help/contact` },
    };
    const app = {
      "@type": "SoftwareApplication",
      name: "TierSaver: List Hygiene for Klaviyo",
      url: `${ORIGIN}/`,
      description: meta.description,
      applicationCategory: "BusinessApplication",
      operatingSystem: "Web",
      publisher: { "@id": `${ORIGIN}/#organization` },
      offers: JSON.parse(tokens["jsonld.offers"]),
    };
    return [jsonLd({ "@context": "https://schema.org", "@graph": [organization, app] })];
  }
  if (meta.layout === "doc" && isListed(page)) {
    const group = GROUPS[meta.group];
    const trail = [{ name: "Home", item: `${ORIGIN}/` }];
    if (group.crumb) trail.push({ name: group.crumb.text, item: `${ORIGIN}${group.crumb.href}` });
    trail.push({ name: meta.nav, item: `${ORIGIN}${page.url}` });
    return [
      jsonLd({
        "@context": "https://schema.org",
        "@type": "BreadcrumbList",
        itemListElement: trail.map((entry, i) => ({ "@type": "ListItem", position: i + 1, ...entry })),
      }),
    ];
  }
  return [];
}

function landingMain(body) {
  return `  <main id="main">\n${body}  </main>`;
}

/** Gives every plain <h2> of an article an id made from its text, so support can link to a section. */
function withHeadingIds(body) {
  const used = new Set([...body.matchAll(/\sid="([^"]+)"/g)].map((m) => m[1]));
  used.add("main");
  return body.replace(/<h2>([^<]+)<\/h2>/g, (whole, text) => {
    const base = text
      .replace(/&[a-z]+;/g, " ")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "");
    if (!base) return whole;
    let id = base;
    for (let n = 2; used.has(id); n++) id = `${base}-${n}`;
    used.add(id);
    return `<h2 id="${id}">${text}</h2>`;
  });
}

function docMain(page, pages, rawBody) {
  const body = withHeadingIds(rawBody);
  const { meta } = page;
  const group = GROUPS[meta.group];
  const crumbs = [`<li><a href="/">Home</a></li>`];
  if (group.crumb) crumbs.push(`<li><a href="${group.crumb.href}">${group.crumb.text}</a></li>`);
  crumbs.push(`<li aria-current="page">${esc(meta.nav)}</li>`);
  const siblings = groupPages(pages, meta.group).map((p) => {
    const current = p === page ? ' aria-current="page"' : "";
    return `            <li><a href="${p.url}"${current}>${esc(p.meta.nav)}</a></li>`;
  });
  return `  <main id="main" class="container doc">
${isLegalDraft(page) ? DRAFT_BANNER : ""}    <nav class="breadcrumb" aria-label="Breadcrumb">
      <ol>
${crumbs.map((c) => `          ${c}`).join("\n")}
      </ol>
    </nav>
    <div class="doc__grid">
      <article class="doc__article">
        <header class="doc__header">
          <p class="label">${esc(meta.kicker ?? group.label)}</p>
          <h1>${esc(meta.title)}</h1>
          <p class="lead">${esc(meta.lead)}</p>
          <p class="label doc__updated"><span>Last updated</span><span>${esc(longDate(meta.updated))}</span></p>
        </header>
        <div class="prose">
${body}        </div>
      </article>
      <aside class="doc__aside">
        <nav aria-label="${group.label}">
          <p class="label">${group.label}</p>
          <ul>
${siblings.join("\n")}
          </ul>
        </nav>
      </aside>
    </div>
  </main>`;
}

function renderPage(page, pages, tokens, partials) {
  let body = fill(page.path, page.body, tokens, partials);
  if (!body.endsWith("\n")) body += "\n";
  const main = page.meta.layout === "doc" ? docMain(page, pages, body) : landingMain(body);
  return `<!doctype html>
<html lang="en">
<head>
${head(page, tokens)}
</head>
<body>
${siteHeader(page)}

${main}

${siteFooter(pages, tokens)}
</body>
</html>
`;
}

function sitemap(pages) {
  const urls = pages
    .filter(isListed)
    .map((p) => p.url)
    .sort();
  return `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls.map((url) => `  <url><loc>${ORIGIN}${url}</loc></url>`).join("\n")}
</urlset>
`;
}

function robots() {
  return `User-agent: *
Allow: /

Sitemap: ${ORIGIN}/sitemap.xml
`;
}

/**
 * Generates every output file in memory. Writes nothing.
 * @returns {Promise<Map<string, string>>} content by path relative to SITE_DIR
 */
export async function generate() {
  const [pages, partials, data, script] = await Promise.all([
    loadPages(),
    loadPartials(),
    loadSiteData(),
    bundleListCheck(),
  ]);
  const tokens = {
    ...data,
    "cta.url": AUDIT_CTA_URL,
    "cta.label": AUDIT_CTA_LABEL,
    "cta.note": AUDIT_CTA_NOTE,
    "contact.email": CONTACT_EMAIL,
    "support.email": SUPPORT_EMAIL,
  };
  // Front-matter values can use the same placeholders as the page bodies.
  for (const page of pages) {
    for (const [key, value] of Object.entries(page.meta)) page.meta[key] = fill(page.path, value, tokens, new Map());
  }
  tokens["list.help"] = linkGrid(pages, "help");
  tokens["list.guides"] = linkGrid(pages, "guide");

  const out = new Map();
  for (const page of pages) out.set(page.path, renderPage(page, pages, tokens, partials));
  out.set("sitemap.xml", sitemap(pages));
  out.set("robots.txt", robots());
  out.set(join("assets", "list-check.js"), script);
  return out;
}

/** Paths of generated files whose content differs from the file on disk. */
export async function staleFiles(generated) {
  const stale = [];
  for (const [path, content] of generated) {
    const onDisk = await readFile(join(SITE_DIR, path), "utf8").catch(() => null);
    if (onDisk !== content) stale.push(path);
  }
  return stale;
}

async function main(argv) {
  const check = argv.includes("--check");
  const generated = await generate();
  const stale = await staleFiles(generated);
  if (check) {
    if (stale.length === 0) {
      console.log(`Up to date: ${generated.size} generated files match site/.`);
      return 0;
    }
    console.error(`Out of date (run \`npm run build\` in site/):\n${stale.map((p) => `  ${p}`).join("\n")}`);
    return 1;
  }
  for (const path of stale) {
    const target = join(SITE_DIR, path);
    await mkdir(dirname(target), { recursive: true });
    await writeFile(target, generated.get(path));
    console.log(`wrote ${path}`);
  }
  console.log(`${generated.size} files generated, ${stale.length} changed.`);
  return 0;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  process.exitCode = await main(process.argv.slice(2)).catch((error) => {
    console.error(error instanceof Error ? error.message : error);
    return 1;
  });
}
